// tests/lfm2_f32_kernels.s -- encoder source for the f32 kernel family.
// Generated bytes are transcribed into lib/std/jit_x86_fused.quanta.
// Every one of these is RE-VERIFIED BY EXECUTION in tests/lfm2_f32_enc_verify.c,
// which runs the exact hex byte sequences with known operands.
//
// The verify_* stubs exist only for that harness: verify_pre loads the test
// registers from a context block (rdi) and verify_post stores them back, so a
// single instruction's real register effects can be inspected from C.
.intel_syntax noprefix
.text

// ===================== harness prologue / epilogue ==========================
// ctx: +0 r9_in, +8 r10_in, +16 rax_out, +24 r9_out, +32 r10_out,
//      +64 ymm0, +128 ymm1, +192 ymm2, +256 ymm3, +320 ymm4, +384 ymm5,
//      +448 ymm6, +512 ymm7, +576 ymm8, +640 ymm9, +960 ymm10, +1024 ymm11,
//      +704 ymm12, +768 ymm13, +832 ymm14, +896 ymm15
.globl verify_pre
verify_pre:
             mov r9, qword ptr [rdi]
             mov r10, qword ptr [rdi+8]
             vmovups ymm0,  ymmword ptr [rdi+64]
             vmovups ymm1,  ymmword ptr [rdi+128]
             vmovups ymm2,  ymmword ptr [rdi+192]
             vmovups ymm3,  ymmword ptr [rdi+256]
             vmovups ymm4,  ymmword ptr [rdi+320]
             vmovups ymm5,  ymmword ptr [rdi+384]
             vmovups ymm6,  ymmword ptr [rdi+448]
             vmovups ymm7,  ymmword ptr [rdi+512]
             vmovups ymm8,  ymmword ptr [rdi+576]
             vmovups ymm9,  ymmword ptr [rdi+640]
             vmovups ymm10, ymmword ptr [rdi+960]
             vmovups ymm11, ymmword ptr [rdi+1024]
             vmovups ymm12, ymmword ptr [rdi+704]
             vmovups ymm13, ymmword ptr [rdi+768]
             vmovups ymm14, ymmword ptr [rdi+832]
             vmovups ymm15, ymmword ptr [rdi+896]
.globl verify_post
verify_post:
             mov qword ptr [rdi+16], rax
             mov qword ptr [rdi+24], r9
             mov qword ptr [rdi+32], r10
             vmovups ymmword ptr [rdi+64],  ymm0
             vmovups ymmword ptr [rdi+128], ymm1
             vmovups ymmword ptr [rdi+192], ymm2
             vmovups ymmword ptr [rdi+256], ymm3
             vmovups ymmword ptr [rdi+320], ymm4
             vmovups ymmword ptr [rdi+384], ymm5
             vmovups ymmword ptr [rdi+448], ymm6
             vmovups ymmword ptr [rdi+512], ymm7
             vmovups ymmword ptr [rdi+576], ymm8
             vmovups ymmword ptr [rdi+640], ymm9
             vmovups ymmword ptr [rdi+960], ymm10
             vmovups ymmword ptr [rdi+1024], ymm11
             vmovups ymmword ptr [rdi+704], ymm12
             vmovups ymmword ptr [rdi+768], ymm13
             vmovups ymmword ptr [rdi+832], ymm14
             vmovups ymmword ptr [rdi+896], ymm15
.globl verify_ret
verify_ret:
             ret

// ---- shared reduce (8 f32 lanes -> f64 in xmm0) ----
.globl r_zero
r_zero:      vxorps ymm0, ymm0, ymm0
.globl r_ext
r_ext:       vextractf128 xmm1, ymm0, 1
.globl r_add
r_add:       vaddps xmm0, xmm0, xmm1
.globl r_hadd
r_hadd:      vhaddps xmm0, xmm0, xmm0
.globl r_widen
r_widen:     vcvtss2sd xmm0, xmm0, xmm0
.globl r_movq
r_movq:      vmovq rax, xmm0

// ---- Q4_K f32 group body ----
.globl a_ldq
a_ldq:       vpmovzxbd ymm1, qword ptr [r9]
.globl a_shl28
a_shl28:     vpslld ymm1, ymm1, 28
.globl a_shr28
a_shr28:     vpsrld ymm1, ymm1, 28
.globl a_shr4
a_shr4:      vpsrld ymm1, ymm1, 4
.globl a_cvt
a_cvt:       vcvtdq2ps ymm1, ymm1
.globl a_mul6
a_mul6:      vmulps ymm1, ymm1, ymm6
.globl a_sub7
a_sub7:      vsubps ymm1, ymm1, ymm7
.globl a_mulr10
a_mulr10:    vmulps ymm1, ymm1, ymmword ptr [r10]
.globl a_acc
a_acc:       vaddps ymm0, ymm0, ymm1
.globl a_addr9
a_addr9:     add r9, 8

// ---- Q4_K f32 factor prologue --------------------------------------------
// THESE REGISTERS ARE THE KERNEL'S, not the f64 kernel's. The first transcription
// of this block was hand-adapted from j_f_fold_factors and left FOUR instructions
// sourcing xmm7 -- the f64 kernel's scratch -- where this kernel keeps its
// unpack result in xmm11. It computed a plausible wrong number. The block is now
// generated straight into lib/std/jit_x86_fused.quanta by
// tests/lfm2_f32_enc_gen.py, so there is nothing to transcribe.
//   xmm2 = [d,dmin,..] f32   ymm8 = broadcast d   ymm9 = broadcast dmin
//   xmm4/5/10 = sc bytes a/b/c as dwords          xmm11 = unpack scratch
//   xmm3 = scratch for the (c & 15) term          ymm12..15 = factor vectors
.globl p_movd
p_movd:      vmovd xmm2, dword ptr [r9-16]
.globl p_ph2ps
p_ph2ps:     vcvtph2ps xmm2, xmm2
.globl p_perm_d
p_perm_d:    vpermilps xmm8, xmm2, 0x00
.globl p_perm_m
p_perm_m:    vpermilps xmm9, xmm2, 0x55
.globl p_ld_a
p_ld_a:      vpmovzxbd xmm4, dword ptr [r9-12]
.globl p_ld_b
p_ld_b:      vpmovzxbd xmm5, dword ptr [r9-8]
.globl p_ld_c
p_ld_c:      vpmovzxbd xmm10, dword ptr [r9-4]
.globl p_shl_a
p_shl_a:     vpslld xmm11, xmm4, 26
.globl p_shr_a
p_shr_a:     vpsrld xmm11, xmm11, 26
.globl p_cvt12
p_cvt12:     vcvtdq2ps xmm12, xmm11
.globl p_mul12
p_mul12:     vmulps xmm12, xmm12, xmm8
.globl p_shl_b
p_shl_b:     vpslld xmm11, xmm5, 26
.globl p_shr_b
p_shr_b:     vpsrld xmm11, xmm11, 26
.globl p_cvt14
p_cvt14:     vcvtdq2ps xmm14, xmm11
.globl p_mul14
p_mul14:     vmulps xmm14, xmm14, xmm9
.globl p_shr_a6
p_shr_a6:    vpsrld xmm11, xmm4, 6
.globl p_shl_a4
p_shl_a4:    vpslld xmm11, xmm11, 4
.globl p_shl_c28
p_shl_c28:   vpslld xmm3, xmm10, 28
.globl p_shr_c28
p_shr_c28:   vpsrld xmm3, xmm3, 28
.globl p_or1
p_or1:       vpor xmm11, xmm11, xmm3
.globl p_cvt13
p_cvt13:     vcvtdq2ps xmm13, xmm11
.globl p_mul13
p_mul13:     vmulps xmm13, xmm13, xmm8
.globl p_shr_b6
p_shr_b6:    vpsrld xmm11, xmm5, 6
.globl p_shl_b4
p_shl_b4:    vpslld xmm11, xmm11, 4
.globl p_shr_c4
p_shr_c4:    vpsrld xmm5, xmm10, 4
.globl p_or2
p_or2:       vpor xmm11, xmm11, xmm5
.globl p_cvt15
p_cvt15:     vcvtdq2ps xmm15, xmm11
.globl p_mul15
p_mul15:     vmulps xmm15, xmm15, xmm9
.globl p_dup12
p_dup12:     vinsertf128 ymm12, ymm12, xmm12, 1
.globl p_dup13
p_dup13:     vinsertf128 ymm13, ymm13, xmm13, 1
.globl p_dup14
p_dup14:     vinsertf128 ymm14, ymm14, xmm14, 1
.globl p_dup15
p_dup15:     vinsertf128 ymm15, ymm15, xmm15, 1

// ---- Q4_K f32 FMA fold ----

// ---- the per-chunk factor broadcast ---------------------------------------
// ONE vpermilps per factor. VPERMILPS's imm8 selectors are LANE-RELATIVE inside
// each 128-bit half -- the trap that cost a peer a day with vpermilpd -- and that
// is exactly what is wanted HERE, because the prologue above left each factor
// vector DUPLICATED into both halves. imm8 = j*0x55 broadcasts lane j of the low
// half to all eight lanes. Verified by execution, including against the real
// prologue's output.
//   chunk 0 -> ymm12 lane 0 / lane 1     chunk 1 -> ymm12 lane 2 / lane 3
//   chunk 2 -> ymm13 lane 0 / lane 1     chunk 3 -> ymm13 lane 2 / lane 3
// and the same four pairs on ymm14/ymm15 for the mins.
.globl p_bc12_00
p_bc12_00:   vpermilps ymm6, ymm12, 0x00
.globl p_bc12_55
p_bc12_55:   vpermilps ymm6, ymm12, 0x55
.globl p_bc12_aa
p_bc12_aa:   vpermilps ymm6, ymm12, 0xaa
.globl p_bc12_ff
p_bc12_ff:   vpermilps ymm6, ymm12, 0xff
.globl p_bc13_00
p_bc13_00:   vpermilps ymm6, ymm13, 0x00
.globl p_bc13_55
p_bc13_55:   vpermilps ymm6, ymm13, 0x55
.globl p_bc13_aa
p_bc13_aa:   vpermilps ymm6, ymm13, 0xaa
.globl p_bc13_ff
p_bc13_ff:   vpermilps ymm6, ymm13, 0xff
.globl p_bc14_00
p_bc14_00:   vpermilps ymm7, ymm14, 0x00
.globl p_bc14_55
p_bc14_55:   vpermilps ymm7, ymm14, 0x55
.globl p_bc14_aa
p_bc14_aa:   vpermilps ymm7, ymm14, 0xaa
.globl p_bc14_ff
p_bc14_ff:   vpermilps ymm7, ymm14, 0xff
.globl p_bc15_00
p_bc15_00:   vpermilps ymm7, ymm15, 0x00
.globl p_bc15_55
p_bc15_55:   vpermilps ymm7, ymm15, 0x55
.globl p_bc15_aa
p_bc15_aa:   vpermilps ymm7, ymm15, 0xaa
.globl p_bc15_ff
p_bc15_ff:   vpermilps ymm7, ymm15, 0xff

.globl a_fnma213
a_fnma213:   vfnmadd213ps ymm1, ymm6, ymm7
.globl a_fnma231
a_fnma231:   vfnmadd231ps ymm0, ymm1, ymmword ptr [r10]

// ---- Q6_K f32 ----
.globl b_ldql
b_ldql:      vpmovzxbd ymm6, qword ptr [r9]
// The DISP8 form, and it is here for a reason that cost a segfault: `as` encodes
// `[r9]` with mod=00, i.e. NO displacement field at all, so the 5-byte sequence
// above is a COMPLETE instruction. Appending a jb(disp8) byte to it inserts that
// byte as the next instruction's first byte and shifts the whole kernel. With a
// non-zero displacement `as` must emit mod=01 + disp8, which is the form the
// kernel needs: 5 bytes of prefix, then the displacement byte.
.globl b_ldql8
b_ldql8:     vpmovzxbd ymm6, qword ptr [r9+8]
.globl b_ldql40
b_ldql40:    vpmovzxbd ymm6, qword ptr [r9+40]
.globl b_ldqh
b_ldqh:      vpmovzxbd ymm7, qword ptr [r9+128]
.globl b_shr4
b_shr4:      vpsrld ymm6, ymm6, 4
.globl b_and4
b_and4:      vpand ymm6, ymm6, ymm4
.globl b_shr2
b_shr2:      vpsrld ymm7, ymm7, 2
.globl b_shr4b
b_shr4b:     vpsrld ymm7, ymm7, 4
.globl b_shr6
b_shr6:      vpsrld ymm7, ymm7, 6
.globl b_and5
b_and5:      vpand ymm7, ymm7, ymm5
.globl b_shl4
b_shl4:      vpslld ymm7, ymm7, 4
.globl b_or
b_or:        vpor ymm6, ymm6, ymm7
.globl b_add3
b_add3:      vpaddd ymm6, ymm6, ymm3
.globl b_cvt
b_cvt:       vcvtdq2ps ymm6, ymm6
.globl b_mul2
b_mul2:      vmulps ymm6, ymm6, ymm2
.globl b_mul1
b_mul1:      vmulps ymm6, ymm6, ymm1
.globl b_mulr10
b_mulr10:    vmulps ymm6, ymm6, ymmword ptr [r10]
.globl b_acc
b_acc:       vaddps ymm0, ymm0, ymm6
.globl b_fma
b_fma:       vfmadd231ps ymm0, ymm6, ymmword ptr [r10]
.globl b_lod
b_lod:       movzx eax, word ptr [r9+208]
.globl b_movdc
b_movdc:     vmovd xmm1, eax
.globl b_ph2ps
b_ph2ps:     vcvtph2ps xmm1, xmm1
.globl b_bcd
b_bcd:       vbroadcastss ymm1, xmm1
.globl b_sc_ld
b_sc_ld:     vpbroadcastb xmm2, byte ptr [r9+192]
.globl b_sc_sext
b_sc_sext:   vpmovsxbd xmm2, xmm2
.globl b_sc_cvt
b_sc_cvt:    vcvtdq2ps xmm2, xmm2
.globl b_sc_bc
b_sc_bc:     vbroadcastss ymm2, xmm2
.globl b_c1
b_c1:        vpcmpeqd ymm3, ymm3, ymm3
.globl b_c2
b_c2:        vpslld ymm3, ymm3, 5
.globl b_c3
b_c3:        vpcmpeqd ymm4, ymm4, ymm4
.globl b_c4
b_c4:        vpsrld ymm4, ymm4, 28
.globl b_c5
b_c5:        vpcmpeqd ymm5, ymm5, ymm5
.globl b_c6
b_c6:        vpsrld ymm5, ymm5, 30

// ===================== f32 CHAIN kernel (tied output projection) ============
// The chain is the reference's strict left-to-right scalar accumulation and a
// lane-based kernel cannot reproduce it, so the fold is EIGHT SERIAL `vaddss`
// in element order -- the f64 chain's shape in `ss` form, and it is the ONLY
// new thing this kernel adds over the f32 matvec family's dequant (which is
// reused verbatim and is already execution-verified above).
//
// ymm6 = [p0,p1,p2,p3,p4,p5,p6,p7] f32 products of ONE 8-element group.
// The accumulator is xmm0 LANE 0 ONLY (`vaddss`, never `vaddps`): the harness
// asserts lane 0 changes AND lanes 1-3 are preserved, which is the difference
// between `ss` and `ps` and the reason a `ps` form here would be a silent wrong
// answer (it would reorder the summation for free).
//
// NOTE the inline comments below use `#`: GNU as takes `#` as the inline comment
// character on x86, while `//` is only recognised at the START of a line. An
// instruction followed by `//` assembles the comment text as OPERANDS
// ("spurious operands; 5 operands/instruction max").
.globl c_ext
c_ext:       vextractf128 xmm7, ymm6, 1     # xmm7 = [p4,p5,p6,p7]
.globl c_add0
c_add0:      vaddss xmm0, xmm0, xmm6        # acc += p0
// The extractions are `vpermilps xmm,imm` -- imm8 selectors are LANE-RELATIVE
// inside the 128-bit source, so 0x55/0xaa/0xff replay lane 1/2/3 into lane 0 of
// the destination and `vaddss` then reads lane 0. Every selector is asserted
// against a known vector in the harness; this is the same imm8 trap that cost a
// peer a day with vpermilpd and it is NOT taken on faith here.
.globl c_pl1
c_pl1:       vpermilps xmm8, xmm6, 0x55     # [p1,p1,p1,p1]
.globl c_add1
c_add1:      vaddss xmm0, xmm0, xmm8        # acc += p1
.globl c_pl2
c_pl2:       vpermilps xmm8, xmm6, 0xaa
.globl c_add2
c_add2:      vaddss xmm0, xmm0, xmm8        # acc += p2
.globl c_pl3
c_pl3:       vpermilps xmm8, xmm6, 0xff
.globl c_add3
c_add3:      vaddss xmm0, xmm0, xmm8        # acc += p3
.globl c_pl4
c_pl4:       vpermilps xmm8, xmm7, 0x00
.globl c_add4
c_add4:      vaddss xmm0, xmm0, xmm8        # acc += p4
.globl c_pl5
c_pl5:       vpermilps xmm8, xmm7, 0x55
.globl c_add5
c_add5:      vaddss xmm0, xmm0, xmm8        # acc += p5
.globl c_pl6
c_pl6:       vpermilps xmm8, xmm7, 0xaa
.globl c_add6
c_add6:      vaddss xmm0, xmm0, xmm8        # acc += p6
.globl c_pl7
c_pl7:       vpermilps xmm8, xmm7, 0xff
.globl c_add7
c_add7:      vaddss xmm0, xmm0, xmm8        # acc += p7
// The final widen: the calling contract is "the dot as f64 bits in rax", and
// the f32 sum is widened ONCE (exact) exactly as the matvec family's reduce
// does. This is the last instruction before `vmovq rax, xmm0`.
.globl c_widen
c_widen:     vcvtss2sd xmm0, xmm0, xmm0
